import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const { user, logout, cart } = useAuth();
  const navigate = useNavigate();

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      navigate(`/catalog?search=${searchTerm}`);
      setIsMobileMenuOpen(false);
    }
  };

  const goToProfileTab = (tab) => {
    if (user) {
      if (tab === 'profile') {
        navigate('/profile');
      } else {
        navigate(`/profile?tab=${tab}`);
      }
    } else {
      navigate('/auth');
    }
    setIsMobileMenuOpen(false);
  };

  const handleLogout = () => {
    logout();
    navigate('/');
    setIsMobileMenuOpen(false);
  };

  // Подсчёт количества товаров в корзине
  const cartItemsCount = cart ? cart.reduce((count, item) => count + (item.quantity || 1), 0) : 0;

  return (
    <nav className="bg-white shadow-lg border-b sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          {/* Logo */}
          <Link to="/" className="flex items-center flex-shrink-0">
            <img 
              src="/images/logo.png" 
              alt="LUNA AUREA" 
              className="h-8 w-auto"
              onError={(e) => {
                e.target.onerror = null;
                e.target.src = "https://via.placeholder.com/150x40/FFD700/000?text=LUNA+AUREA";
              }}
            />
            <span className="ml-2 text-xl font-serif font-bold hidden sm:block">LUNA AUREA</span>
          </Link>

          {/* Desktop Navigation Links */}
          <div className="hidden md:flex space-x-8">
            <Link to="/catalog" className="text-gray-700 hover:text-gold-600 transition-colors">КАТАЛОГ</Link>
            <Link to="/collections" className="text-gray-700 hover:text-gold-600 transition-colors">КОЛЛЕКЦИИ</Link>
            <Link to="/about" className="text-gray-700 hover:text-gold-600 transition-colors">О НАС</Link>
            <Link to="/contacts" className="text-gray-700 hover:text-gold-600 transition-colors">КОНТАКТЫ</Link>
          </div>

          {/* Icons */}
          <div className="flex items-center space-x-2 sm:space-x-4">
            {/* Search */}
            <form onSubmit={handleSearch} className="relative hidden xs:block">
              <input
                type="text"
                placeholder="Поиск..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-3 pr-10 py-1.5 border rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-gold-500 w-32 sm:w-40 lg:w-48"
              />
              <button 
                type="submit" 
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gold-600"
              >
                🔍
              </button>
            </form>

            {/* Mobile menu button */}
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="md:hidden p-2 rounded-md text-gray-700 hover:text-gold-600 hover:bg-gray-100 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-gold-500"
              aria-label="Toggle menu"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {isMobileMenuOpen ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                )}
              </svg>
            </button>

            {/* Desktop Icons */}
            <div className="hidden md:flex items-center space-x-2">
              {/* Profile */}
              {user ? (
                <div className="relative group">
                  <button 
                    className="p-2 hover:bg-gray-100 rounded-full transition-colors"
                    title={`${user.username || user.email}`}
                  >
                    <div className="w-6 h-6 rounded-full bg-gold-600 text-white flex items-center justify-center text-xs font-bold">
                      {user.username ? user.username.charAt(0).toUpperCase() : user.email.charAt(0).toUpperCase()}
                    </div>
                  </button>
                  <div className="absolute right-0 mt-2 w-56 bg-white rounded-md shadow-lg py-1 z-50 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 border">
                    <div className="px-4 py-2 border-b">
                      <p className="text-sm font-medium">{user.username || 'Пользователь'}</p>
                      <p className="text-xs text-gray-500 truncate">{user.email}</p>
                    </div>
                    <button
                      onClick={() => navigate('/profile')}
                      className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-gold-600"
                    >
                      👤 Мой профиль
                    </button>
                    <button
                      onClick={() => navigate('/profile?tab=orders')}
                      className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 hover:text-gold-600"
                    >
                      📦 Мои заказы
                    </button>
                    <button
                      onClick={handleLogout}
                      className="block w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-gray-100"
                    >
                      🚪 Выйти
                    </button>
                  </div>
                </div>
              ) : (
                <Link 
                  to="/auth" 
                  className="p-2 hover:bg-gray-100 rounded-full transition-colors"
                  title="Войти или зарегистрироваться"
                >
                  👤
                </Link>
              )}

              {/* Favorites */}
              <button 
                onClick={() => goToProfileTab('favorites')}
                className="p-2 hover:bg-gray-100 rounded-full transition-colors"
                title="Избранное"
              >
                ❤️
              </button>

              {/* Cart */}
              <button 
                onClick={() => goToProfileTab('cart')}
                className="p-2 hover:bg-gray-100 rounded-full relative transition-colors"
                title="Корзина"
              >
                🛒
                {cartItemsCount > 0 && (
                  <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-5 h-5 text-xs flex items-center justify-center">
                    {cartItemsCount}
                  </span>
                )}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden absolute left-0 right-0 top-16 bg-white border-b shadow-lg z-40">
            <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
              {/* Mobile Search */}
              <form onSubmit={handleSearch} className="px-3 pb-3">
                <div className="relative">
                  <input
                    type="text"
                    placeholder="Поиск..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gold-500"
                  />
                  <button 
                    type="submit" 
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500"
                  >
                    🔍
                  </button>
                </div>
              </form>

              <Link
                to="/catalog"
                className="block px-3 py-3 text-gray-700 hover:text-gold-600 hover:bg-gray-50 rounded-md border-b"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                КАТАЛОГ
              </Link>
              <Link
                to="/collections"
                className="block px-3 py-3 text-gray-700 hover:text-gold-600 hover:bg-gray-50 rounded-md border-b"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                КОЛЛЕКЦИИ
              </Link>
              <Link
                to="/about"
                className="block px-3 py-3 text-gray-700 hover:text-gold-600 hover:bg-gray-50 rounded-md border-b"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                О НАС
              </Link>
              <Link
                to="/contacts"
                className="block px-3 py-3 text-gray-700 hover:text-gold-600 hover:bg-gray-50 rounded-md border-b"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                КОНТАКТЫ
              </Link>

              {/* Mobile Auth Actions */}
              <div className="pt-4 pb-3 border-t border-gray-200">
                {user ? (
                  <div className="px-3 space-y-3">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="font-medium">Привет, {user.username || 'Пользователь'}!</p>
                        <p className="text-xs text-gray-500">{user.email}</p>
                      </div>
                      <button
                        onClick={handleLogout}
                        className="text-sm text-red-600 hover:text-red-800 px-3 py-1 border border-red-600 rounded"
                      >
                        Выйти
                      </button>
                    </div>
                    <div className="flex space-x-4">
                      <button 
                        onClick={() => goToProfileTab('favorites')}
                        className="p-2 hover:bg-gray-100 rounded-full"
                        title="Избранное"
                      >
                        ❤️
                      </button>
                      <button 
                        onClick={() => goToProfileTab('cart')}
                        className="p-2 hover:bg-gray-100 rounded-full relative"
                        title="Корзина"
                      >
                        🛒
                        {cartItemsCount > 0 && (
                          <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-4 h-4 text-xs flex items-center justify-center">
                            {cartItemsCount}
                          </span>
                        )}
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="px-3">
                    <p className="text-sm text-gray-600 mb-3">Войдите, чтобы управлять профилем</p>
                    <div className="flex space-x-3">
                      <Link
                        to="/auth"
                        className="flex-1 text-center bg-gold-600 hover:bg-gold-700 text-white px-4 py-2 rounded"
                        onClick={() => setIsMobileMenuOpen(false)}
                      >
                        Войти
                      </Link>
                      <Link
                        to="/auth"
                        className="flex-1 text-center border border-gold-600 text-gold-600 hover:bg-gold-50 px-4 py-2 rounded"
                        onClick={() => setIsMobileMenuOpen(false)}
                      >
                        Регистрация
                      </Link>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
